def find_between_9s(arr, positions):
    """Find indices between consecutive 9s in the array"""
    between = []
    for k in range(1, len(positions)):
        start, end = positions[k-1], positions[k]
        between.extend(range(start + 1, end))
    return between

def test_both_rules(grid_in, grid_out):
    rows = len(grid_in)
    cols = len(grid_in[0])

    errors = []
    total = rows * cols

    for i in range(rows):
        for j in range(cols):
            inp = grid_in[i][j]
            out = grid_out[i][j]

            if inp == 9:
                if out != 9:
                    errors.append(f"({i},{j}): 9 -> {out}")
                continue

            # Check if 4 should become 2
            in_row_between = False
            row_cells = [grid_in[i][k] for k in range(cols)]
            nine_positions = [k for k in range(cols) if row_cells[k] == 9]
            between_positions = find_between_9s(row_cells, nine_positions)
            if j in between_positions:
                in_row_between = True

            in_col_between = False
            col_cells = [grid_in[k][j] for k in range(rows)]
            nine_positions_col = [k for k in range(rows) if col_cells[k] == 9]
            between_positions_col = find_between_9s(col_cells, nine_positions_col)
            if i in between_positions_col:
                in_col_between = True

            # All 4s between consecutive 9s should be 2, others stay 4
            if in_row_between or in_col_between:
                expected = 2
                if out != 2:
                    errors.append(f"({i},{j}): is 4, in_row={in_row_between}, in_col={in_col_between}, got {out}")
            else:
                expected = 4
                if out != 4:
                    errors.append(f"({i},{j}): is 4, not between 9s, got {out}")

    print(f"Rule: Test passed = {len(errors) == 0}")
    print(f"Total cells: {total}, Errors: {len(errors)}")
    if errors:
        print("First 10 errors:")
        for e in errors[:10]:
            print(f"  {e}")

