def list_horizontal_transforms(grid_in, grid_out):
    """List all horizontal transformations and their gaps"""
    rows = len(grid_in)
    cols = len(grid_in[0])

    transforms = []  # (row, gap_size) for each 4→2

    for i in range(rows):
        row_in = [grid_in[i][j] for j in range(cols)]
        nine_pos = [j for j in range(cols) if row_in[j] == 9]

        for k in range(1, len(nine_pos)):
            start, end = nine_pos[k-1], nine_pos[k]
            gap_size = end - start - 1
            if gap_size > 0:
                for j in range(start+1, end):
                    if grid_in[i][j] == 4 and grid_out[i][j] == 2:
                        transforms.append((i, gap_size, j))
                    elif grid_in[i][j] == 4 and grid_out[i][j] == 4:
                        transforms.append((i, gap_size, j, "no-change"))

    # Show sample horizontal gaps
    print("Horizontal gaps in each row:")
    for i in range(rows):
        row_in = [grid_in[i][j] for j in range(cols)]
        nine_pos = [j for j in range(cols) if row_in[j] == 9]

        for k in range(1, len(nine_pos)):
            start, end = nine_pos[k-1], nine_pos[k]
            gap_size = end - start - 1
            print(f"Row {i}: 9s at {nine_pos}, gap of {gap_size} between {start}-{end}")

    # Show gaps that DON'T transform
    no_transform = []
    for i, gap_size, j, flag in transforms:
        if flag == "no-change":
            no_transform.append((i, gap_size))
    print(f"\nHorizontal gaps with no transformation: {no_transform}")

