def apply_rule_horizontal(grid_in, max_gap):
    """Apply horizontal transformation 4->2 between consecutive 9s with gap <= max_gap"""
    rows = len(grid_in)
    cols = len(grid_in[0])

    result = [[grid_in[i][j] for j in range(cols)] for i in range(rows)]

    for i in range(rows):
        nine_pos = [j for j in range(cols) if result[i][j] == 9]

        for k in range(1, len(nine_pos)):
            start, end = nine_pos[k-1], nine_pos[k]
            gap_size = end - start - 1

            if gap_size <= max_gap:
                for j in range(start+1, end):
                    if result[i][j] == 4:
                        result[i][j] = 2

    return result

def apply_rule_vertical(grid_in, max_gap):
    """Apply vertical transformation 4->2 between consecutive 9s with gap <= max_gap"""
    rows = len(grid_in)
    cols = len(grid_in[0])

    result = [[grid_in[i][j] for j in range(cols)] for i in range(rows)]

    for j in range(cols):
        nine_pos = [i for i in range(rows) if result[i][j] == 9]

        for k in range(1, len(nine_pos)):
            start, end = nine_pos[k-1], nine_pos[k]
            gap_size = end - start - 1

            if gap_size <= max_gap:
                for i in range(start+1, end):
                    if result[i][j] == 4:
                        result[i][j] = 2

    return result

